    "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>LeapOS-Gateway</title>\n  <style>\n    :root {\n      --bg: #0f1419;\n      --panel: #161b22;\n      --border: #30363d;\n      --text: #e6edf3;\n      --muted: #8b949e;\n      --accent: #58c4ff;\n      --ok: #238636;\n      --warn: #d29922;\n    }\n    * { box-sizing: border-box; }\n    body {\n      font-family: system-ui, sans-serif;\n      margin: 0;\n      background: var(--bg);\n      color: var(--text);\n      line-height: 1.45;\n    }\n    main { max-width: 1080px; margin: 0 auto; padding: 1.5rem; }\n    h1 { color: var(--accent); margin: 0 0 .25rem; }\n    h2 { margin: 1.75rem 0 .75rem; font-size: 1.1rem; }\n    p.muted { color: var(--muted); margin-top: 0; }\n    .toolbar { display: flex; flex-wrap: wrap; gap: .5rem; margin: 1rem 0; }\n    button, .btn {\n      background: var(--ok);\n      color: #fff;\n      border: 0;\n      padding: .55rem 1rem;\n      cursor: pointer;\n      border-radius: 6px;\n      font: inherit;\n    }\n    button.secondary { background: #21262d; border: 1px solid var(--border); }\n    button.warn { background: #8957e5; }\n    button:hover { filter: brightness(1.08); }\n    button.small { padding: .25rem .55rem; font-size: .85rem; }\n    .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: .75rem; }\n    .card {\n      background: var(--panel);\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      padding: 1rem;\n    }\n    label { display: block; font-size: .85rem; color: var(--muted); margin-bottom: .25rem; }\n    input, select {\n      width: 100%;\n      background: var(--bg);\n      color: var(--text);\n      border: 1px solid var(--border);\n      border-radius: 6px;\n      padding: .45rem .55rem;\n      font: inherit;\n    }\n    input[type=checkbox] { width: auto; margin-right: .4rem; }\n    table { border-collapse: collapse; width: 100%; margin-top: .5rem; }\n    th, td { border: 1px solid var(--border); padding: .5rem; text-align: left; vertical-align: middle; }\n    th { background: var(--panel); }\n    pre {\n      background: var(--panel);\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      padding: 1rem;\n      overflow: auto;\n      font-size: .85rem;\n    }\n    #msg {\n      min-height: 1.25rem;\n      margin: .75rem 0;\n      color: var(--accent);\n    }\n    #msg.error { color: #f85149; }\n    .row-inline { display: flex; align-items: center; gap: .5rem; margin-top: .5rem; }\n    .hint { font-size: .82rem; color: var(--muted); margin-top: .35rem; }\n    code { background: #21262d; padding: .1rem .35rem; border-radius: 4px; }\n    .bits { font-family: ui-monospace, monospace; letter-spacing: .08em; }\n    .bit {\n      display: inline-block;\n      width: 1.1rem;\n      text-align: center;\n      margin-right: .15rem;\n      border-radius: 3px;\n      background: #21262d;\n      color: #8b949e;\n    }\n    .bit.on { background: #238636; color: #fff; }\n    .io-ok { color: #3fb950; }\n    .io-bad { color: #f85149; }\n  </style>\n</head>\n<body>\n<main>\n  <h1>LeapOS-Gateway</h1>\n  <p class=\"muted\">Configuration UI v2 - discover LEAP devices, map assemblies, save config.</p>\n\n  <div class=\"toolbar\">\n    <button id=\"scan\">Scan LEAP</button>\n    <button class=\"secondary\" id=\"connect_leap\">Connect LEAP</button>\n    <button class=\"secondary\" id=\"reload\">Reload config</button>\n    <button class=\"secondary\" id=\"status\">Refresh status</button>\n    <button id=\"save\">Apply to runtime</button>\n    <button class=\"warn\" id=\"persist\">Save to disk</button>\n  </div>\n  <div id=\"msg\"></div>\n\n  <h2>Network</h2>\n  <div class=\"card grid\">\n    <div>\n      <label for=\"ipv4\">IPv4 address</label>\n      <input id=\"ipv4\" type=\"text\" placeholder=\"192.168.1.2\">\n    </div>\n    <div>\n      <label for=\"mask\">Subnet mask</label>\n      <input id=\"mask\" type=\"text\" placeholder=\"255.255.255.0\">\n    </div>\n    <div>\n      <label for=\"cyclic_ms\">LEAP cyclic period (ms)</label>\n      <input id=\"cyclic_ms\" type=\"number\" min=\"10\" max=\"1000\" step=\"1\">\n    </div>\n    <div>\n      <label for=\"ifname\">Interface</label>\n      <input id=\"ifname\" type=\"text\" placeholder=\"re0\">\n    </div>\n  </div>\n  <p class=\"hint\">IP changes take effect after reboot. <strong>Save to disk</strong> requires boot from the CF/IDE image (<code>leapos-gateway.img</code>), not the ISO alone.</p>\n\n  <h2>EtherNet/IP assemblies (PLC connection)</h2>\n  <div class=\"card\">\n    <p>Use these in Studio 5000 / RSLinx exclusive-owner connection:</p>\n    <ul>\n      <li>Input assembly <code>100</code> (32 bytes) - gateway -&gt; PLC</li>\n      <li>Output assembly <code>150</code> (32 bytes) - PLC -&gt; gateway</li>\n      <li>Config assembly <code>151</code> (10 bytes)</li>\n    </ul>\n  </div>\n\n  <h2>LEAP peer mapping</h2>\n  <div class=\"card grid\">\n    <div>\n      <label for=\"map_mac\">Peer MAC</label>\n      <input id=\"map_mac\" type=\"text\" placeholder=\"aa:bb:cc:dd:ee:ff\">\n    </div>\n    <div>\n      <label for=\"map_profile\">Profile ID</label>\n      <input id=\"map_profile\" type=\"text\" placeholder=\"0x00010001\">\n    </div>\n    <div>\n      <label for=\"map_input_byte\">Input byte (E/IP asm 100)</label>\n      <input id=\"map_input_byte\" type=\"number\" min=\"0\" max=\"31\">\n    </div>\n    <div>\n      <label for=\"map_output_byte\">Output byte (E/IP asm 150)</label>\n      <input id=\"map_output_byte\" type=\"number\" min=\"0\" max=\"31\">\n    </div>\n    <div>\n      <label for=\"map_status_byte\">Status byte (E/IP asm 100)</label>\n      <input id=\"map_status_byte\" type=\"number\" min=\"0\" max=\"31\">\n    </div>\n    <div>\n      <label for=\"map_width\">Digital width (bits)</label>\n      <input id=\"map_width\" type=\"number\" min=\"1\" max=\"16\" value=\"8\">\n    </div>\n  </div>\n  <div class=\"row-inline\">\n    <label><input id=\"map_enabled\" type=\"checkbox\"> Enable this mapping</label>\n  </div>\n  <p class=\"hint\">Pick a discovered peer with <strong>Map</strong>, enable mapping, then <strong>Apply</strong>. Use <strong>Connect LEAP</strong> to bootstrap ownership (DISC -&gt; MGMT -&gt; OP) on demand. Use <strong>Save to disk</strong> so the mapping survives reboot.</p>\n\n  <h2>Live I/O monitor</h2>\n  <div class=\"row-inline\">\n    <label><input id=\"io_auto\" type=\"checkbox\" checked> Auto-refresh (500 ms)</label>\n    <button class=\"secondary small\" id=\"io_refresh\">Refresh I/O</button>\n    <span id=\"io_session\" class=\"muted\"></span>\n  </div>\n  <table>\n    <thead>\n      <tr>\n        <th>Peer</th><th>Comm</th>\n        <th>LEAP inputs<br><span class=\"muted\">device -&gt; gateway</span></th>\n        <th>LEAP outputs<br><span class=\"muted\">gateway -&gt; device</span></th>\n        <th>E/IP in byte<br><span class=\"muted\">asm 100 -&gt; PLC</span></th>\n        <th>E/IP out byte<br><span class=\"muted\">asm 150 &lt;- PLC</span></th>\n      </tr>\n    </thead>\n    <tbody id=\"io_rows\"><tr><td colspan=\"6\" class=\"muted\">Waiting for data...</td></tr></tbody>\n  </table>\n  <p class=\"hint\">Updates when the gateway owns the LEAP session (phase <code>OP</code>) and cyclic PD is running. LEAP inputs are digital inputs read from the device; LEAP outputs are driven from the E/IP output assembly.</p>\n\n  <h2>Discovered peers</h2>\n  <table>\n    <thead>\n      <tr><th>MAC</th><th>Profile</th><th>State</th><th>Owner</th><th></th></tr>\n    </thead>\n    <tbody id=\"peers\"></tbody>\n  </table>\n\n  <h2>Status</h2>\n  <pre id=\"stat\">Loading...</pre>\n\n  <h2>Raw config preview</h2>\n  <pre id=\"config_preview\"></pre>\n</main>\n<script>\nconst LEAP_STATES = {\n  '0x0000': 'BOOT', '0x0001': 'INIT', '0x0002': 'CONFIGURED',\n  '0x0003': 'SAFE', '0x0004': 'OP', '0x0005': 'FAULT'\n};\n\nconst defaults = {\n  ipv4: '192.168.1.2',\n  mask: '255.255.255.0',\n  cyclic_ms: 50,\n  ifname: 're0',\n  map_mac: '',\n  map_profile: '0x00010001',\n  map_input_byte: 0,\n  map_output_byte: 2,\n  map_status_byte: 4,\n  map_width: 8,\n  map_enabled: false\n};\n\nfunction $(id) { return document.getElementById(id); }\n\nfunction showMsg(text, isError) {\n  const el = $('msg');\n  el.textContent = text;\n  el.className = isError ? 'error' : '';\n}\n\nfunction parseConfigText(text) {\n  const cfg = {\n    network: { ipv4: defaults.ipv4, mask: defaults.mask, ifname: defaults.ifname },\n    cyclic_ms: defaults.cyclic_ms,\n    mapping: {\n      enabled: defaults.map_enabled,\n      mac: defaults.map_mac,\n      profile: defaults.map_profile,\n      input_byte: defaults.map_input_byte,\n      output_byte: defaults.map_output_byte,\n      status_byte: defaults.map_status_byte,\n      width: defaults.map_width\n    }\n  };\n  let active = null;\n\n  for (const rawLine of text.split('\\n')) {\n    const line = rawLine.trim();\n    if (!line || line.startsWith('#')) continue;\n    const eq = line.indexOf('=');\n    if (eq < 0) continue;\n    const key = line.slice(0, eq).trim();\n    const value = line.slice(eq + 1).trim();\n\n    switch (key) {\n      case 'network.ipv4': cfg.network.ipv4 = value; break;\n      case 'network.mask': cfg.network.mask = value; break;\n      case 'network.ifname': cfg.network.ifname = value; break;\n      case 'cyclic_ms': cfg.cyclic_ms = Number(value) || defaults.cyclic_ms; break;\n      case 'mapping.begin': active = Number(value); break;\n      case 'mapping.enabled': if (active === 0) cfg.mapping.enabled = value === '1' || value === 'true'; break;\n      case 'mapping.mac': if (active === 0) cfg.mapping.mac = value.toLowerCase(); break;\n      case 'mapping.profile': if (active === 0) cfg.mapping.profile = value; break;\n      case 'mapping.input.byte': if (active === 0) cfg.mapping.input_byte = Number(value); break;\n      case 'mapping.output.byte': if (active === 0) cfg.mapping.output_byte = Number(value); break;\n      case 'mapping.status.byte': if (active === 0) cfg.mapping.status_byte = Number(value); break;\n      case 'mapping.input.width':\n      case 'mapping.output.width':\n        if (active === 0) cfg.mapping.width = Number(value);\n        break;\n      default: break;\n    }\n  }\n  return cfg;\n}\n\nfunction buildConfigText() {\n  const mac = $('map_mac').value.trim().toLowerCase();\n  const profile = $('map_profile').value.trim() || '0x00010001';\n  const enabled = $('map_enabled').checked ? 1 : 0;\n  const width = Number($('map_width').value) || 8;\n\n  return [\n    '# LeapOS-Gateway configuration',\n    'network.mode=single',\n    `network.ifname=${$('ifname').value.trim() || 're0'}`,\n    `network.ipv4=${$('ipv4').value.trim()}`,\n    `network.mask=${$('mask').value.trim()}`,\n    'network.dhcp=0',\n    `cyclic_ms=${Number($('cyclic_ms').value) || 50}`,\n    'mapping.begin=0',\n    `mapping.enabled=${enabled}`,\n    `mapping.mac=${mac || '00:00:00:00:00:00'}`,\n    `mapping.profile=${profile}`,\n    `mapping.input.byte=${Number($('map_input_byte').value) || 0}`,\n    `mapping.input.bit=0`,\n    `mapping.input.width=${width}`,\n    `mapping.output.byte=${Number($('map_output_byte').value) || 2}`,\n    `mapping.output.bit=0`,\n    `mapping.output.width=${width}`,\n    `mapping.status.byte=${Number($('map_status_byte').value) || 4}`\n  ].join('\\n') + '\\n';\n}\n\nfunction applyConfigToForm(cfg) {\n  $('ipv4').value = cfg.network.ipv4;\n  $('mask').value = cfg.network.mask;\n  $('ifname').value = cfg.network.ifname;\n  $('cyclic_ms').value = cfg.cyclic_ms;\n  $('map_mac').value = cfg.mapping.mac;\n  $('map_profile').value = cfg.mapping.profile;\n  $('map_input_byte').value = cfg.mapping.input_byte;\n  $('map_output_byte').value = cfg.mapping.output_byte;\n  $('map_status_byte').value = cfg.mapping.status_byte;\n  $('map_width').value = cfg.mapping.width;\n  $('map_enabled').checked = cfg.mapping.enabled;\n  $('config_preview').textContent = buildConfigText();\n}\n\nasync function loadConfig() {\n  const r = await fetch('/api/v1/config');\n  if (!r.ok) throw new Error('Failed to load config');\n  const text = await r.text();\n  applyConfigToForm(parseConfigText(text));\n}\n\nfunction fmtBits(value, width) {\n  let out = '';\n  const w = Math.min(Math.max(width || 8, 1), 16);\n  for (let bit = w - 1; bit >= 0; bit--) {\n    const on = (value >> bit) & 1;\n    out += `<span class=\"bit ${on ? 'on' : 'off'}\">${on}</span>`;\n  }\n  return out;\n}\n\nfunction fmtHexByte(v) {\n  return '0x' + (v & 0xFF).toString(16).toUpperCase().padStart(2, '0');\n}\n\nasync function loadIo() {\n  const r = await fetch('/api/v1/io');\n  if (!r.ok) throw new Error('I/O read failed');\n  const data = await r.json();\n  const tbody = $('io_rows');\n  const session = $('io_session');\n\n  session.textContent =\n    `Session: ${data.leap_phase}${data.session_active ? ' (owner)' : ''}` +\n    (data.leap_comm_ok ? '' : ' - no PD comm');\n\n  const rows = (data.mappings || []).filter(m => m.enabled);\n  if (rows.length === 0) {\n    tbody.innerHTML = '<tr><td colspan=\"6\" class=\"muted\">No enabled mappings</td></tr>';\n    return;\n  }\n\n  tbody.innerHTML = '';\n  rows.forEach(m => {\n    const tr = document.createElement('tr');\n    const comm = m.comm_ok\n      ? '<span class=\"io-ok\">OK</span>'\n      : '<span class=\"io-bad\">-</span>';\n    tr.innerHTML = `\n      <td>${m.mac}</td>\n      <td>${comm}</td>\n      <td><div>${fmtHexByte(m.leap_inputs)}</div><div class=\"bits\">${fmtBits(m.leap_inputs, m.input_width_bits)}</div></td>\n      <td><div>${fmtHexByte(m.leap_outputs)}</div><div class=\"bits\">${fmtBits(m.leap_outputs, m.output_width_bits)}</div></td>\n      <td>${fmtHexByte(m.eip_input_byte)} <span class=\"bits\">${fmtBits(m.eip_input_byte, m.input_width_bits)}</span></td>\n      <td>${fmtHexByte(m.eip_output_byte)} <span class=\"bits\">${fmtBits(m.eip_output_byte, m.output_width_bits)}</span></td>`;\n    tbody.appendChild(tr);\n  });\n}\n\nlet ioTimer = null;\nfunction startIoPoll() {\n  if (ioTimer) clearInterval(ioTimer);\n  if (!$('io_auto').checked) return;\n  ioTimer = setInterval(() => loadIo().catch(() => {}), 500);\n}\n\n$('io_refresh').onclick = () => loadIo().catch(e => showMsg(e.message, true));\n$('io_auto').onchange = startIoPoll;\n\nasync function loadStatus() {\n  const r = await fetch('/api/v1/status');\n  const data = await r.json();\n  $('stat').textContent = JSON.stringify(data, null, 2);\n  if (data.storage_ready === false) {\n    showMsg('Config volume not mounted - Apply works in RAM; Save to disk needs CF/IDE boot (not read-only ISO).', true);\n  } else if (data.leap_session_active) {\n    showMsg(`LEAP owner session active (${data.leap_phase})`);\n  } else if (data.leap_phase && data.leap_phase !== 'IDLE') {\n    showMsg(`LEAP session state: ${data.leap_phase}`);\n  }\n}\n\nasync function loadPeers() {\n  const r = await fetch('/api/v1/leap/peers');\n  const data = await r.json();\n  const tbody = $('peers');\n  tbody.innerHTML = '';\n  (data.peers || []).forEach(p => {\n    const tr = document.createElement('tr');\n    const stateLabel = LEAP_STATES[p.state] ? `${LEAP_STATES[p.state]} (${p.state})` : p.state;\n    tr.innerHTML = `\n      <td>${p.mac}</td>\n      <td>${p.profile}</td>\n      <td>${stateLabel}</td>\n      <td>${p.owner}</td>\n      <td><button class=\"small btn map-peer\" data-mac=\"${p.mac}\" data-profile=\"${p.profile}\">Map</button></td>`;\n    tbody.appendChild(tr);\n  });\n  tbody.querySelectorAll('.map-peer').forEach(btn => {\n    btn.onclick = () => {\n      $('map_mac').value = btn.dataset.mac;\n      $('map_profile').value = btn.dataset.profile;\n      $('map_enabled').checked = true;\n      $('config_preview').textContent = buildConfigText();\n      showMsg(`Mapped peer ${btn.dataset.mac}`);\n    };\n  });\n}\n\nasync function applyConfig() {\n  const body = buildConfigText();\n  $('config_preview').textContent = body;\n  const r = await fetch('/api/v1/config', { method: 'PUT', body });\n  const text = await r.text();\n  if (!r.ok) throw new Error(text || 'Apply failed');\n  showMsg('Configuration applied. Click Connect LEAP when ready. IP changes still need reboot.');\n}\n\nasync function connectLeap() {\n  const r = await fetch('/api/v1/leap/connect', { method: 'POST' });\n  const text = await r.text();\n  if (!r.ok) throw new Error(text || 'Connect failed');\n  showMsg('LEAP connect requested.');\n  await loadStatus();\n}\n\nasync function persistConfig() {\n  await applyConfig();\n  const r = await fetch('/api/v1/config/apply', { method: 'POST' });\n  const text = await r.text();\n  if (!r.ok) throw new Error(text || 'Save failed');\n  showMsg('Configuration saved to disk.');\n}\n\nfunction wirePreviewUpdates() {\n  ['ipv4','mask','ifname','cyclic_ms','map_mac','map_profile','map_input_byte',\n   'map_output_byte','map_status_byte','map_width','map_enabled'].forEach(id => {\n    $(id).addEventListener('input', () => {\n      $('config_preview').textContent = buildConfigText();\n    });\n    $(id).addEventListener('change', () => {\n      $('config_preview').textContent = buildConfigText();\n    });\n  });\n}\n\n$('scan').onclick = async () => {\n  showMsg('Scanning LEAP network...');\n  await fetch('/api/v1/leap/discover?scan_ms=1000', { method: 'POST' });\n  await new Promise(r => setTimeout(r, 1200));\n  await loadPeers();\n  showMsg('Scan complete.');\n};\n\n$('connect_leap').onclick = async () => {\n  try {\n    await connectLeap();\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\n$('reload').onclick = async () => {\n  try {\n    await loadConfig();\n    showMsg('Configuration loaded.');\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\n$('status').onclick = () => loadStatus().catch(e => showMsg(e.message, true));\n\n$('save').onclick = async () => {\n  try {\n    await applyConfig();\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\n$('persist').onclick = async () => {\n  try {\n    await persistConfig();\n  } catch (e) {\n    showMsg(e.message, true);\n  }\n};\n\nwirePreviewUpdates();\nloadConfig().catch(() => applyConfigToForm({ network: defaults, cyclic_ms: defaults.cyclic_ms, mapping: {\n  enabled: defaults.map_enabled, mac: defaults.map_mac, profile: defaults.map_profile,\n  input_byte: defaults.map_input_byte, output_byte: defaults.map_output_byte,\n  status_byte: defaults.map_status_byte, width: defaults.map_width\n}}));\nloadStatus();\nloadPeers();\nloadIo().catch(() => {});\nstartIoPoll();\n</script>\n</body>\n</html>\n";

